    }
    void showDebt(const Debt & rd)
    {
        showPerson(rd.name);
        std::cout <<": $" << rd.amount << std::endl;
    }
    double sumDebts(const Debt ar[], int n)

{
    double total = 0;
    for (int i = 0; i < n; i++)
        total += ar[i].amount;
    return total;
}
